input.command:
cd docs
for f in $(grep -rl "webhook-service" --include="*.md" .); do
  echo "###### $f ######"
  awk '/^\*\*Satisfies:|^- \*\*Satisfies:|^\*\*Code:|^- \*\*Code:|^\*\*Implemented by:|^- \*\*Implemented by:/{print NR": "$0}' "$f" > /tmp/tags_$$.txt
  # print blocks where Code or Implemented-by line contains webhook-service, along with preceding Satisfies line
  awk '
    /Satisfies:/ {sat=$0; satline=NR}
    /Code:|Implemented by:/ {
      if ($0 ~ /webhook-service/) {
        print "Satisfies("satline"): " sat
        print "Code/Impl("NR"): " $0
        print "---"
      }
    }
  ' "$f"
done
